final class MasterElixirsRuntime {
 static void run(GameTestHelper h,AlchemyRuntime.Walk w)throws Exception{var p=w.p;var server=p.server;server.tickRateManager().setTickRate(20);var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.ALCHEMIST);if(track.completedQuestIds().contains(BrewQuests.EXPEDITION)){h.assertTrue(track.xp()==2700&&track.completedQuestIds().size()==17&&w.authenticatedCount(BrewQuests.EXPEDITION)==3,"Actual17earned2700XP and three legitimate surplus native identities restore");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MASTER_ELIXIRS_RESTART_PASSED: actual8healingII8swiftnessII8fire-resistance spent identities/native receipt/three legitimate leftovers/17earned2700XP/old16proofs/original Nessa-lab restore");h.succeed();return;}
  h.assertTrue(track.xp()==2400&&track.completedQuestIds().size()==16,"Starts from actual full8A8J, no Master rank fixture");stash(h,w);DimensionTravelRuntimeTests.seed(server,7);h.assertTrue(!NativeOutputQuests.eligible(p,BrewQuests.EXPEDITION,true),"Tier7cannot qualify for approved Tier8Master brewing");DimensionTravelRuntimeTests.seed(server,8);var recipes=BrewQuests.recipes(BrewQuests.EXPEDITION);var healing=recipes.stream().filter(r->r.output().equals("strong_healing")).findFirst().orElseThrow();for(int n=0;n<3;n++){w.start(healing);w.tick(401);if(n==0)w.claimRevocation(BrewQuests.EXPEDITION);w.collect(BrewQuests.EXPEDITION);}w.counter();boolean quota=false;try{ProfessionService.review(p,"enchanted:"+BrewQuests.EXPEDITION);}catch(IllegalStateException expected){quota=true;}h.assertTrue(quota,"Authentic healing-only production cannot substitute for all three families");
  // Copy only an already genuine identity adversarially; this never issues new canonical proof.
  int original=-1;for(int i=0;i<36;i++)if(p.getInventory().getItem(i).getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(EnchantedToolService.KEY).hasUUID("id")){original=i;break;}h.assertTrue(original>=0,"Real native output available for copy refusal");var copied=p.getInventory().getItem(original).copy();var temporaries=new ArrayList<Integer>();for(int n=0;n<15;n++){int free=p.getInventory().getFreeSlot();h.assertTrue(free>=0,"Temporary adversarial copies fit without overwriting inventory");p.getInventory().setItem(free,copied.copy());temporaries.add(free);}boolean copy=false;try{ProfessionService.review(p,"enchanted:"+BrewQuests.EXPEDITION);}catch(IllegalStateException expected){copy=true;}h.assertTrue(copy&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==2400,"Copied physical tags cannot create24distinct authentic quota outputs");for(int slot:temporaries)p.getInventory().setItem(slot,net.minecraft.world.item.ItemStack.EMPTY);
  for(var recipe:recipes)if(recipe!=healing)for(int n=0;n<3;n++){w.start(recipe);w.tick(401);w.collect(BrewQuests.EXPEDITION);}w.counter();h.assertTrue(w.authenticatedCount(BrewQuests.EXPEDITION)==27,"Actual native3slot cycles produce exactly9of each family; no output proof injection");var q=ProfessionService.review(p,"enchanted:"+BrewQuests.EXPEDITION);ProfessionService.confirm(p,q.nonce());boolean replay=false;try{ProfessionService.review(p,"enchanted:"+BrewQuests.EXPEDITION);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&w.authenticatedCount(BrewQuests.EXPEDITION)==3&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==2700&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).completedQuestIds().size()==17,"Exactly8of each physical family consumed atomically for300XPonce; real leftovers retain rights");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MASTER_ELIXIRS_NATIVE_PASSED: Tier7refusal/Tier8real native paid glowstone/magma/fuel27potions/three family quota/currentFTBcollection/copied-identity/replay refusals/permanent exact8+8+8delivery/17earned2700XP/original16proofs; private raw inputs/native brewing tick acceleration/Tier8boundary only, no source/XP/quest/rank/output proof injection");h.succeed();
 }
 /** Preserve every earlier physical item in actual existing permitted storage; never delete it to make room. */
 static void stash(GameTestHelper h,AlchemyRuntime.Walk w){var p=w.p;for(var at:net.minecraft.core.BlockPos.betweenClosed(w.center.offset(-8,-1,-8),w.center.offset(8,2,8))){if(!(w.level.getBlockEntity(at) instanceof net.minecraft.world.level.block.entity.BarrelBlockEntity barrel)||com.mohymods.kingdomsmp.placement.PlacementProtection.check(w.level,p,at,at)!=null)continue;for(int slot=0;slot<36;slot++){if(p.getInventory().getItem(slot).isEmpty())continue;int free=-1;for(int n=0;n<barrel.getContainerSize();n++)if(barrel.getItem(n).isEmpty()){free=n;break;}if(free<0)break;barrel.setItem(free,p.getInventory().removeItemNoUpdate(slot));}barrel.setChanged();}h.assertTrue(java.util.stream.IntStream.range(0,36).allMatch(i->p.getInventory().getItem(i).isEmpty()),"Existing genuine private storage holds all old physical items before native full commission");}
}
